const input = $input.first().json;
const body = input.body || input;
const intent = String(body.intent || '');
const vacancyId = Number(body.vacancy_id);
const candidateId = Number(body.candidate_id);
if (!intent) { throw new Error('Вход требует intent'); }
const lastRun = "run_id = (SELECT run_id FROM recruiter_compass.candidate_reviews WHERE potok_vacancy_id = " + vacancyId + " ORDER BY created_at DESC LIMIT 1)";
const criteria_sql = "SELECT criteria_version_id, criteria FROM recruiter_compass.vacancy_criteria_versions WHERE potok_vacancy_id = " + vacancyId + " AND status = 'confirmed' ORDER BY version_number DESC LIMIT 1";
const review_sql = "SELECT potok_candidate_id, evidence, critical_unknowns, summary FROM recruiter_compass.candidate_reviews WHERE potok_vacancy_id = " + vacancyId + " AND potok_candidate_id = " + candidateId + " ORDER BY created_at DESC LIMIT 1";
const strong_sql = "SELECT potok_candidate_id FROM recruiter_compass.candidate_reviews WHERE potok_vacancy_id = " + vacancyId + " AND recommendation = 'continue' AND " + lastRun + " ORDER BY potok_candidate_id";
const weak_sql = "SELECT potok_candidate_id, evidence, summary FROM recruiter_compass.candidate_reviews WHERE potok_vacancy_id = " + vacancyId + " AND recommendation = 'not_for_current_vacancy' AND " + lastRun + " ORDER BY potok_candidate_id";
const middle_sql = "SELECT potok_candidate_id, critical_unknowns, summary FROM recruiter_compass.candidate_reviews WHERE potok_vacancy_id = " + vacancyId + " AND recommendation = 'clarify' AND " + lastRun + " ORDER BY potok_candidate_id";
return [{ json: { intent: intent, vacancy_id: vacancyId, candidate_id: candidateId, criteria_sql: criteria_sql, review_sql: review_sql, strong_sql: strong_sql, weak_sql: weak_sql, middle_sql: middle_sql } }];

const items = $input.all();
const objs = (items[0] && items[0].json && items[0].json.objects) || [];
return objs.filter(function(i) { return i.active === true; }).map(function(i) { return { json: { applicant_id: i.applicant_id } }; });

const resumes = $input.all();
const criteriaRow = $('Критерии вакансии').first().json;
const criteria = criteriaRow.criteria;
const criteriaVersionId = criteriaRow.criteria_version_id;
return resumes.map(function(r) {
  const reviewInput = 'ID кандидата: ' + r.json.applicant_id + '\nИмя: ' + (r.json.name || '') + '\n\nКритерии вакансии (JSON): ' + JSON.stringify(criteria) + '\n\nРезюме кандидата: ' + (r.json.resume_text || '');
  return { json: { candidate_id: String(r.json.applicant_id), candidate_name: r.json.name || '', criteria_version_id: criteriaVersionId, review_input: reviewInput } };
});

const items = $input.all();
const assembleItems = $('Собрать вход разбора').all();
const criteria = $('Критерии вакансии').first().json.criteria;
const mustHaveIds = (criteria || []).filter(function(c) { return c.kind === 'must_have'; }).map(function(c) { return c.criterion_id; });
const cvId = assembleItems[0].json.criteria_version_id;
const recMap = { continue: 'continue', clarify: 'clarify', not_for_current_role: 'not_for_current_vacancy', consider_neighbour_role: 'consider_neighbour_role' };
return items.map(function(item, idx) {
  const o = item.json.output || {};
  const a = assembleItems[idx].json;
  const assessments = o.assessments || [];
  const mustStates = assessments.filter(function(x) { return mustHaveIds.indexOf(x.criterion_id) >= 0; }).map(function(x) { return x.state; });
  let nextAction = 'continue';
  if (mustStates.indexOf('not_met') >= 0) { nextAction = 'not_for_current_role'; }
  else if (mustStates.indexOf('needs_clarification') >= 0) { nextAction = 'clarify'; }
  const recommendation = recMap[nextAction];
  return { json: { candidate_id: o.candidate_id, candidate_name: a.candidate_name, recommendation: recommendation, summary: o.reasoning_summary || '', evidence: assessments, critical_unknowns: o.critical_unknowns || [], criteria_version_id: cvId } };
});

const items = $input.all();
const cvId = items[0] ? items[0].json.criteria_version_id : '';
const vacId = Number($('Валидировать вход').first().json.vacancy_id);
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const rows = items.map(function(i) { return "(" + Number(i.json.candidate_id) + ",'" + esc(i.json.recommendation) + "','" + esc(i.json.summary) + "','" + esc(JSON.stringify(i.json.evidence)) + "','" + esc(JSON.stringify(i.json.critical_unknowns)) + "')"; }).join(', ');
const sql = "WITH new_run AS (INSERT INTO recruiter_compass.agent_runs (workflow_key, trigger_source, status, potok_vacancy_id, model_provider, model_name, prompt_version) VALUES ('review_candidates','webhook','succeeded'," + vacId + ",'deepseek','deepseek-chat','candidate-review-v1') RETURNING run_id) INSERT INTO recruiter_compass.candidate_reviews (run_id, potok_candidate_id, potok_vacancy_id, criteria_version_id, recommendation, summary, evidence, critical_unknowns) SELECT run_id, v.candidate_id, " + vacId + ", '" + esc(cvId) + "', v.rec, v.summary, v.evidence::jsonb, v.unknowns::jsonb FROM new_run, (VALUES " + rows + ") AS v(candidate_id, rec, summary, evidence, unknowns)";
const criteria = $('Критерии вакансии').first().json.criteria || [];
const titleMap = {};
criteria.forEach(function(c) { if (c && c.criterion_id) { titleMap[c.criterion_id] = c.title; } });
const ids = Object.keys(titleMap).sort(function(a, b) { return b.length - a.length; });
const clean = function(t) { if (t === undefined || t === null) { return t; } var s = String(t); ids.forEach(function(k) { s = s.split(k).join(titleMap[k]); }); return s; };
const stateLabel = { confirmed: 'подтверждено', partially_confirmed: 'частично', needs_clarification: 'уточнить', not_met: 'не соответствует' };
const recLabel = { continue: 'вести дальше', clarify: 'уточнить', not_for_current_vacancy: 'не подходит', consider_neighbour_role: 'соседняя роль' };
const overview = { 'continue': [], 'clarify': [], 'not_for_current_vacancy': [] };
items.forEach(function(i) { (overview[i.json.recommendation] || overview['clarify']).push({ candidate_id: i.json.candidate_id, name: i.json.candidate_name, summary: clean(i.json.summary) }); });
const cards = items.map(function(i) {
  const evidence = (i.json.evidence || []).map(function(e) {
    return { title: titleMap[e.criterion_id] || e.criterion_id, state: stateLabel[e.state] || e.state, claim: clean(e.claim) };
  });
  const unknowns = (i.json.critical_unknowns || []).map(function(u) {
    return { title: titleMap[u.criterion_id] || u.criterion_id, question: clean(u.question), why_now: clean(u.why_now) };
  });
  return { candidate_id: i.json.candidate_id, name: i.json.candidate_name, recommendation: recLabel[i.json.recommendation] || i.json.recommendation, evidence: evidence, critical_unknowns: unknowns, summary: clean(i.json.summary) };
});
return [{ json: { sql: sql, overview: overview, cards: cards, count: items.length } }];

