const criteria = $('Критерии (бриф)').first().json.criteria;
const review = $('Разбор (бриф)').first().json;
const app = $('Кандидат (бриф)').first().json;
const reviewInput = 'Критерии вакансии (JSON): ' + JSON.stringify(criteria) + '\n\nРазбор кандидата (assessments): ' + JSON.stringify(review.evidence) + '\n\nКритические пробелы: ' + JSON.stringify(review.critical_unknowns);
return [{ json: { candidate_id: String(review.potok_candidate_id), candidate_name: app.name || '', review_input: reviewInput } }];

function iso(offsetDays, hour) { const d = new Date(); d.setDate(d.getDate() + offsetDays); d.setHours(hour, 0, 0, 0); return d.toISOString(); }
const items = $input.all();
return items.map(function(item) {
  const slots = [
    { id: 'slot-1', label: 'завтра 11:00–12:00', from: iso(1, 11), to: iso(1, 12) },
    { id: 'slot-2', label: 'завтра 14:00–15:00', from: iso(1, 14), to: iso(1, 15) },
    { id: 'slot-3', label: 'послезавтра 11:00–12:00', from: iso(2, 11), to: iso(2, 12) }
  ];
  return { json: { candidate_id: String(item.json.id), candidate_name: item.json.name || '', slots: slots } };
});

const reviews = $('Слабые кандидаты').all();
const apps = $input.all();
return apps.map(function(app, idx) {
  const rev = reviews[idx].json;
  const input = 'Кандидат: ' + app.json.name + '\n\nРазбор по критериям (JSON): ' + JSON.stringify(rev.evidence);
  return { json: { candidate_id: String(app.json.id), candidate_name: app.json.name, message_input: input } };
});

